{
  "decision": "accept",
  "icd10_code": "E11.22",
  "code_display": "Type 2 DM with diabetic CKD",
  "guideline_citations": [
    {
      "url": "https://www.cms.gov/files/document/fy-2027-icd-10-cm-coding-guidelines.pdf",
      "quote": "The classification presumes a causal relationship between the two conditions linked by these terms in the Alphabetic Index or Tabular List. These conditions should be coded as related even in the absence of provider documentation explicitly linking them, unless the documentation clearly states the conditions are unrelated or when another guideline exists that specifically requires a documented linkage between two conditions (e.g., sepsis guideline for “acute organ dysfunction that is not clearly associated with the sepsis”).",
      "source": "ICD-10-CM Official Guidelines for Coding and Reporting FY 2027"
    }
  ],
  "rationale": "The chart contains multiple affirmative statements: 'Type 2 diabetes mellitus.', 'Chronic kidney disease stage 3.', 'type 2 diabetes mellitus with hyperglycemia is active.', and 'Diabetic nephropathy is active.' The mention windows show no retractions, negations, family history attributions, screening language, hypothetical phrasing, or resolved status. The explicit documentation of diabetic nephropathy directly links the diabetes and CKD, satisfying the combination code requirement. The guideline excerpt confirms that a causal relationship is presumed for such linked conditions. No physician query is needed as the evidence is clear and unambiguous.",
  "physician_query_needed": false
}
